-- Généré depuis le catalogue source. Ne pas éditer manuellement.
-- Retire uniquement les anciennes lignes de démonstration remplacées par le catalogue réel.
delete from public.products where slug in ('huile-corporelle-fleur-d-oranger', 'gommage-corporel-fleur-d-oranger', 'masque-capillaire-fleur-d-oranger', 'parfum-cheveux-fleur-d-oranger', 'shampooing-the-vert', 'lait-corporel-ambre-musc');

on conflict (slug) do update set
  sku = excluded.sku,
  name = excluded.name,
  description = excluded.description,
  price_eur = excluded.price_eur,
  status = excluded.status,
  image_url = excluded.image_url,
  metadata = excluded.metadata,
  updated_at = now();

select c.id, p.id, row_number() over (partition by c.id order by p.name, p.slug)::integer
from public.products p
join public.collections c on c.slug = p.metadata->>'fragrance'
on conflict (collection_id, product_id) do update set position = excluded.position;
