insert into public.products (sku, slug, name, description, price_eur, stock_quantity, low_stock_threshold, status, image_url, metadata)
values
  ('MLZ-BO-100', 'body-oil-fleur-doranger', 'Huile Corporelle', 'La fleur d''oranger, c''est le printemps marocain — les patios, le carrelage frais, l''eau que l''on vous tend à l''entrée. Cette huile la garde dans son flacon d''ambre, pour être travaillée lentement sur la peau, en fin de journée.', 13.64, 25, 10, 'active', '/products/fleur-doranger/body-oil/shop/02-clean-product.png', '{"productType":"body-oil","fragrance":"fleur-doranger","scent":"Fleur d''Oranger","size":"100 ML","volumeMl":100,"withArgan":false,"ritual":"body","needs":["nourish","glow","scent"],"ingredients":["orange-blossom"],"aspect":"tall","featured":true,"imageWidth":364,"imageHeight":1217,"gallery":["/products/fleur-doranger/body-oil/shop/02-clean-product.png","/products/body-oil.webp"],"localized":{"name":{"en":"Body Oil","fr":"Huile Corporelle","ar":"زيت الجسم"},"tagline":{"en":"Orange blossom, carried in oil.","fr":"La fleur d''oranger, portée par l''huile.","ar":"زهر البرتقال، محمولاً في الزيت."},"description":{"en":"Orange blossom is the scent of a Moroccan spring — courtyards, cool tiled floors, water offered at the door. This body oil carries it in amber glass, to be worked into the skin slowly, at the end of a day.","fr":"La fleur d''oranger, c''est le printemps marocain — les patios, le carrelage frais, l''eau que l''on vous tend à l''entrée. Cette huile la garde dans son flacon d''ambre, pour être travaillée lentement sur la peau, en fin de journée.","ar":"زهر البرتقال هو رائحة الربيع المغربي: الأفنية، البلاط البارد، والماء الذي يُقدَّم عند الباب. يحفظ هذا الزيت تلك الرائحة في زجاج عنبري، ليُدلَّك على البشرة بتمهّل في آخر النهار."},"ritualNote":{"en":"After the hammam, or a long shower, while the skin is still warm.","fr":"Après le hammam, ou une longue douche, tant que la peau est encore chaude.","ar":"بعد الحمّام أو استحمام طويل، والبشرة ما تزال دافئة."},"howToUse":{"en":"Warm a little between the palms. Work upward from the ankles, unhurried. Finish at the shoulders.","fr":"Réchauffez quelques gouttes entre les paumes. Remontez des chevilles, sans hâte. Terminez aux épaules.","ar":"دفّئي قليلاً منه بين الكفّين. اصعدي من الكاحلين بلا عجلة، وانتهي عند الكتفين."},"vessel":{"en":"Frosted amber glass, brass-toned collar, ornamental label.","fr":"Verre ambré dépoli, col ton laiton, étiquette ornementale.","ar":"زجاج عنبري مصنفر، طوق بلون النحاس، وملصق مزخرف."}}}'::jsonb),
  ('MLZ-HP-100', 'hair-perfume-fleur-doranger', 'Parfum Pour Cheveux', 'Un parfum pour cheveux bâti sur la fleur d''oranger. Plus léger qu''un parfum de peau : il bouge quand vous bougez, et reste quelques pas derrière vous.', 30.92, 25, 10, 'active', '/products/fleur-doranger/hair-perfume/shop/02-clean-product.png', '{"productType":"hair-perfume","fragrance":"fleur-doranger","scent":"Fleur d''Oranger","size":"100 ML","volumeMl":100,"withArgan":false,"ritual":"scent","needs":["scent"],"ingredients":["orange-blossom"],"aspect":"tall","featured":true,"imageWidth":363,"imageHeight":1115,"gallery":["/products/fleur-doranger/hair-perfume/shop/02-clean-product.png","/products/hair-perfume.webp"],"localized":{"name":{"en":"Hair Perfume","fr":"Parfum Pour Cheveux","ar":"عطر الشعر"},"tagline":{"en":"Scent, worn in the hair.","fr":"Le parfum, porté dans les cheveux.","ar":"عطرٌ يُلبَس في الشعر."},"description":{"en":"A hair perfume built on fleur d''oranger. Lighter than fragrance on skin: it moves when you move, and stays a few steps behind you.","fr":"Un parfum pour cheveux bâti sur la fleur d''oranger. Plus léger qu''un parfum de peau : il bouge quand vous bougez, et reste quelques pas derrière vous.","ar":"عطر للشعر قوامه زهر البرتقال. أخفّ من عطر البشرة: يتحرّك حين تتحرّكين، ويبقى على بعد خطوات خلفك."},"ritualNote":{"en":"Last, once the hair is dry.","fr":"En dernier, une fois les cheveux secs.","ar":"في الأخير، بعد أن يجفّ الشعر."},"howToUse":{"en":"Hold at arm''s length. Two passes over the lengths — never the roots.","fr":"Vaporisez à bout de bras. Deux passages sur les longueurs — jamais sur les racines.","ar":"امسكي القارورة على مسافة الذراع. رشّتان على الأطراف — لا على الجذور."},"vessel":{"en":"Frosted amber glass, brass-toned collar, ornamental label.","fr":"Verre ambré dépoli, col ton laiton, étiquette ornementale.","ar":"زجاج عنبري مصنفر، طوق بلون النحاس، وملصق مزخرف."}}}'::jsonb),
  ('MLZ-BS-250', 'body-scrub-argan-fleur-doranger', 'Gommage Corporel', 'Le gommage est le cœur du hammam marocain — le moment où la semaine s''en va. Formulé à l''huile d''argan et parfumé à la fleur d''oranger, dans le plus grand pot de la maison.', 13.64, 25, 10, 'active', '/products/fleur-doranger/body-scrub/shop/02-clean-product.png', '{"productType":"body-scrub","fragrance":"fleur-doranger","scent":"Fleur d''Oranger","size":"250 ML","volumeMl":250,"withArgan":true,"ritual":"hammam","needs":["cleanse","glow"],"ingredients":["argan","orange-blossom"],"aspect":"jar","featured":true,"imageWidth":723,"imageHeight":848,"gallery":["/products/fleur-doranger/body-scrub/shop/02-clean-product.png","/products/body-scrub.webp"],"localized":{"name":{"en":"Body Scrub","fr":"Gommage Corporel","ar":"مقشّر الجسم"},"tagline":{"en":"The hammam, at home.","fr":"Le hammam, à la maison.","ar":"الحمّام، في بيتك."},"description":{"en":"Gommage is the centre of the Moroccan hammam — the moment the week is taken off. Made with argan oil and scented with fleur d''oranger, in the largest jar the house fills.","fr":"Le gommage est le cœur du hammam marocain — le moment où la semaine s''en va. Formulé à l''huile d''argan et parfumé à la fleur d''oranger, dans le plus grand pot de la maison.","ar":"الگمّاج قلب الحمّام المغربي — اللحظة التي يُنزَع فيها أسبوع كامل. مصنوع بزيت الأركان ومعطّر بزهر البرتقال، في أكبر مرطبان تملؤه الدار."},"ritualNote":{"en":"Once a week, in a warm room, before anything else.","fr":"Une fois par semaine, dans une pièce chaude, avant tout le reste.","ar":"مرّة في الأسبوع، في غرفة دافئة، قبل كل شيء آخر."},"howToUse":{"en":"On damp skin. Work in circles from the ankles upward. Rinse, then oil.","fr":"Sur peau humide. Massez en cercles, des chevilles vers le haut. Rincez, puis huilez.","ar":"على بشرة رطبة. دلّكي بحركات دائرية من الكاحلين صعوداً. اشطفي، ثم رطّبي بالزيت."},"vessel":{"en":"Amber glass jar, screw-threaded brass-toned lid.","fr":"Pot en verre ambré, couvercle vissé ton laiton.","ar":"مرطبان من الزجاج العنبري بغطاء لولبي بلون النحاس."}}}'::jsonb),
  ('MLZ-HM-200', 'hair-mask-argan-fleur-doranger', 'Masque Capillaire', 'Un masque hebdomadaire à l''huile d''argan, en verre ambré sous un couvercle ton laiton. Le genre de pot qui reste sur l''étagère, pas dans le placard.', 12.73, 25, 10, 'active', '/products/fleur-doranger/hair-mask/shop/02-clean-product.png', '{"productType":"hair-mask","fragrance":"fleur-doranger","scent":"Fleur d''Oranger","size":"200 ML","volumeMl":200,"withArgan":true,"ritual":"hair","needs":["nourish","restore"],"ingredients":["argan","orange-blossom"],"aspect":"jar","featured":true,"imageWidth":798,"imageHeight":938,"gallery":["/products/fleur-doranger/hair-mask/shop/02-clean-product.png","/products/hair-mask.webp"],"localized":{"name":{"en":"Hair Mask","fr":"Masque Capillaire","ar":"قناع الشعر"},"tagline":{"en":"A longer treatment, for the ends.","fr":"Un soin plus long, pour les pointes.","ar":"عناية أطول، للأطراف."},"description":{"en":"A weekly mask with argan oil, in amber glass under a brass-toned lid. The kind of jar that stays out on the shelf rather than in the cupboard.","fr":"Un masque hebdomadaire à l''huile d''argan, en verre ambré sous un couvercle ton laiton. Le genre de pot qui reste sur l''étagère, pas dans le placard.","ar":"قناع أسبوعي بزيت الأركان، في زجاج عنبري تحت غطاء بلون النحاس. من المرطبانات التي تبقى على الرفّ لا في الخزانة."},"ritualNote":{"en":"Once a week. Give it the ten minutes.","fr":"Une fois par semaine. Accordez-lui ses dix minutes.","ar":"مرّة في الأسبوع. امنحيه عشر دقائق كاملة."},"howToUse":{"en":"On damp hair. Section, apply to lengths and ends, leave ten minutes, rinse.","fr":"Sur cheveux humides. Séparez, appliquez sur les longueurs et les pointes, laissez dix minutes, rincez.","ar":"على شعر رطب. قسّمي الشعر، ووزّعيه على الأطوال والأطراف، واتركيه عشر دقائق ثم اشطفي."},"vessel":{"en":"Amber glass jar, screw-threaded brass-toned lid.","fr":"Pot en verre ambré, couvercle vissé ton laiton.","ar":"مرطبان من الزجاج العنبري بغطاء لولبي بلون النحاس."}}}'::jsonb),
  ('MLZ-SH-200', 'shampoo-argan-fleur-doranger', 'Shampooing', 'Un shampooing à l''huile d''argan et à la fleur d''oranger, achevé d''un pompon de soie noué à la main — la petite exigence de la maison : que le quotidien soit habillé, lui aussi.', 10, 25, 10, 'active', '/products/fleur-doranger/shampoo/shop/02-clean-product.png', '{"productType":"shampoo","fragrance":"fleur-doranger","scent":"Fleur d''Oranger","size":"200 ML","volumeMl":200,"withArgan":true,"ritual":"hair","needs":["cleanse"],"ingredients":["argan","orange-blossom"],"aspect":"column","featured":false,"imageWidth":408,"imageHeight":1212,"gallery":["/products/fleur-doranger/shampoo/shop/02-clean-product.png","/products/shampoo.webp"],"localized":{"name":{"en":"Shampoo","fr":"Shampooing","ar":"شامبو"},"tagline":{"en":"The first step, dressed properly.","fr":"Le premier geste, correctement habillé.","ar":"الخطوة الأولى، في لباسها اللائق."},"description":{"en":"A shampoo with argan oil and fleur d''oranger, finished with a hand-tied silk tassel — the house''s small insistence that the everyday should also be dressed.","fr":"Un shampooing à l''huile d''argan et à la fleur d''oranger, achevé d''un pompon de soie noué à la main — la petite exigence de la maison : que le quotidien soit habillé, lui aussi.","ar":"شامبو بزيت الأركان وزهر البرتقال، مذيَّل بشرّابة حرير معقودة يدوياً — إصرار الدار الصغير على أن اليومي يستحقّ لباسه أيضاً."},"ritualNote":{"en":"The opening of the hair ritual.","fr":"L''ouverture du rituel capillaire.","ar":"افتتاح طقس الشعر."},"howToUse":{"en":"Work into wet hair at the scalp. Rinse. Repeat only if you need to.","fr":"Massez le cuir chevelu sur cheveux mouillés. Rincez. Ne recommencez que si nécessaire.","ar":"دلّكي فروة الرأس على شعر مبلل. اشطفي. وكرّري عند الحاجة فقط."},"vessel":{"en":"Ornamented bottle, domed cap, hand-tied silk tassel.","fr":"Flacon ornementé, capuchon en dôme, pompon de soie noué à la main.","ar":"قارورة مزخرفة، غطاء مقبّب، وشرّابة حرير معقودة يدوياً."}}}'::jsonb),
  ('MLZ-CD-200', 'conditioner-argan-fleur-doranger', 'Après-Shampooing', 'Le compagnon du shampooing, à l''huile d''argan et à la même fleur d''oranger. On le laisse le temps d''une longue respiration, puis on rince.', 11.82, 25, 10, 'active', '/products/fleur-doranger/conditioner/shop/02-clean-product.png', '{"productType":"conditioner","fragrance":"fleur-doranger","scent":"Fleur d''Oranger","size":"200 ML","volumeMl":200,"withArgan":true,"ritual":"hair","needs":["nourish","restore"],"ingredients":["argan","orange-blossom"],"aspect":"column","featured":false,"imageWidth":410,"imageHeight":1260,"gallery":["/products/fleur-doranger/conditioner/shop/02-clean-product.png","/products/conditioner.webp"],"localized":{"name":{"en":"Conditioner","fr":"Après-Shampooing","ar":"بلسم الشعر"},"tagline":{"en":"What follows the wash.","fr":"Ce qui suit le lavage.","ar":"ما يلي الغسل."},"description":{"en":"The companion to the shampoo, with argan oil and the same orange blossom. Left in for the length of a long breath, then rinsed.","fr":"Le compagnon du shampooing, à l''huile d''argan et à la même fleur d''oranger. On le laisse le temps d''une longue respiration, puis on rince.","ar":"رفيق الشامبو، بزيت الأركان وبزهر البرتقال نفسه. يُترك بمقدار نَفَسٍ طويل، ثم يُشطف."},"ritualNote":{"en":"Straight after the shampoo, every wash.","fr":"Juste après le shampooing, à chaque lavage.","ar":"مباشرة بعد الشامبو، في كلّ غسلة."},"howToUse":{"en":"Apply from mid-length to ends. Leave two to three minutes. Rinse cool.","fr":"Appliquez des mi-longueurs aux pointes. Laissez deux à trois minutes. Rincez à l''eau fraîche.","ar":"وزّعيه من منتصف الطول إلى الأطراف. اتركيه دقيقتين إلى ثلاث. اشطفي بماء بارد."},"vessel":{"en":"Ornamented bottle, domed cap, hand-tied silk tassel.","fr":"Flacon ornementé, capuchon en dôme, pompon de soie noué à la main.","ar":"قارورة مزخرفة، غطاء مقبّب، وشرّابة حرير معقودة يدوياً."}}}'::jsonb),
  ('MLZ-BM-200', 'body-milk-argan-fleur-doranger', 'Lait Corporel', 'Un lait corporel à l''huile d''argan pour les matins où l''huile est de trop. Pompe, pompon doré, fleur d''oranger — la même maison, dans un registre plus léger.', 11.82, 25, 10, 'active', '/products/fleur-doranger/body-milk/shop/02-clean-product.png', '{"productType":"body-milk","fragrance":"fleur-doranger","scent":"Fleur d''Oranger","size":"200 ML","volumeMl":200,"withArgan":true,"ritual":"body","needs":["hydrate","scent"],"ingredients":["argan","orange-blossom"],"aspect":"column","featured":true,"imageWidth":475,"imageHeight":1336,"gallery":["/products/fleur-doranger/body-milk/shop/02-clean-product.png","/products/body-milk.webp"],"localized":{"name":{"en":"Body Milk","fr":"Lait Corporel","ar":"حليب الجسم"},"tagline":{"en":"Lighter than the oil. For every day.","fr":"Plus léger que l''huile. Pour tous les jours.","ar":"أخفّ من الزيت. لكلّ يوم."},"description":{"en":"A body milk with argan oil for the mornings when oil is too much. Pump, gold tassel, orange blossom — the same house, in a lighter register.","fr":"Un lait corporel à l''huile d''argan pour les matins où l''huile est de trop. Pompe, pompon doré, fleur d''oranger — la même maison, dans un registre plus léger.","ar":"حليب للجسم بزيت الأركان، لصباحاتٍ يكون فيها الزيت أثقل من اللازم. مضخّة، وشرّابة ذهبية، وزهر برتقال — الدار نفسها بنبرة أخفّ."},"ritualNote":{"en":"Mornings, on skin still damp from the shower.","fr":"Le matin, sur une peau encore humide de la douche.","ar":"في الصباح، على بشرة ما تزال رطبة من الاستحمام."},"howToUse":{"en":"Two pumps. Smooth over arms, legs and shoulders. Dress once it has settled.","fr":"Deux pressions. Lissez sur les bras, les jambes et les épaules. Habillez-vous une fois absorbé.","ar":"ضغطتان. وزّعيه على الذراعين والساقين والكتفين، والبسي بعد أن يستقرّ."},"vessel":{"en":"Ornamented bottle, brass-toned pump, gold silk tassel.","fr":"Flacon ornementé, pompe ton laiton, pompon de soie doré.","ar":"قارورة مزخرفة، مضخّة بلون النحاس، وشرّابة حرير ذهبية."}}}'::jsonb),
