  ('MLZ-TV-BM-200', 'body-milk-the-vert', 'Lait Corporel', 'Lait Corporel · Thé Vert', 11.82, 25, 10, 'active', '/products/the-vert/body-milk/shop/02-clean-product.png', '{"productType":"body-milk","fragrance":"the-vert","scent":"Thé Vert","size":"200 ML","volumeMl":200,"withArgan":true,"ritual":"body","needs":[],"ingredients":[],"aspect":"column","featured":false,"imageWidth":1600,"imageHeight":899,"gallery":["/products/the-vert/body-milk/shop/02-clean-product.png","/products/the-vert/body-milk/02-clean-product.jpeg","/products/the-vert/body-milk/03-alternate.jpeg","/products/the-vert/body-milk/02-clean-product.webp"],"localized":{"name":{"en":"Body Milk","fr":"Lait Corporel","ar":"حليب الجسم"},"tagline":{"en":"","fr":"","ar":""},"description":{"en":"","fr":"","ar":""},"ritualNote":{"en":"","fr":"","ar":""},"howToUse":{"en":"","fr":"","ar":""},"vessel":{"en":"","fr":"","ar":""}}}'::jsonb),
